const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ar = (s, cls='') => `<span lang="ar" class="ar ${cls}">${esc(s)}</span>`;
const steps = [ ['Welcome','مرحباً بكن','Introduction'], ['Watch & wonder','شاهدي وفكري','Interactive video'], ['Play & discover','العبِي واكتشفي','Predict · try · explain'], ['The dirham challenge','تحدي الدرهم','A quick check'], ['Probability sprint','سباق الاحتمالات','10-question competition'], ['Mastery quest','رحلة الإتقان','12-question practice'], ['Exit reflection','تأمل ختامي','Your voice matters'], ['My learning story','رحلتي التعليمية','Progress & print'] ];
