let state=null, slide=0, loginRole='student', teacherTab='monitor', dashboard=null, activeGame=null, gameFeedback=null, quizBusy=false, timerInterval=null, monitorInterval=null, heartbeatInterval=null, player=null, videoInterval=null, activeCheckpoint=null, checkpointSeen=new Set(), spin=0, flipCount=0, linked=true;
const app=$('#app');
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
async function api(path, body){
 const res=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),credentials:'same-origin'});
 const type=res.headers.get('content-type')||'';
 if(!type.includes('application/json')) throw new Error('Classroom server unavailable. Start the app with python3 server.py. GitHub Pages alone cannot sync student progress.');
 const data=await res.json();
 if(!res.ok) throw new Error(data.error||'Unable to connect. Please try again.');
 return data;
}
function coin(face='heads', draggable=false){return `<div class="coin-obj object" ${draggable?'data-drag tabindex="0" role="button" aria-label="Move dirham with arrow keys or drag"':''}>${face==='heads'?`<span class="coin-text">UNITED ARAB EMIRATES</span><svg viewBox="0 0 64 64" aria-label="Dallah coffee pot, dirham heads illustration"><path d="M20 24h23l-2 25H24zM22 24l5-7h9l5 7M28 16v-5h7v5M42 28c19-9 18 14-1 13M23 28L9 21l6 19 9 5M25 49h15M24 54h19"/><path d="M28 29l-1 15M37 29l1 15"/></svg><span class="coin-text">دِرْهَم · DALLAH</span>`:`<span class="coin-text">الإمارات العربية المتحدة</span><span class="coin-value">1</span><span class="coin-text">دِرْهَم · DIRHAM</span>`}</div>`}
function die(n=5, draggable=false){const on={1:[4],2:[0,8],3:[0,4,8],4:[0,2,6,8],5:[0,2,4,6,8],6:[0,2,3,5,6,8]}[n];return `<div class="die-obj object" aria-label="Die showing ${n}" ${draggable?'data-drag tabindex="0" role="button"':''}>${Array.from({length:9},(_,i)=>`<i class="${on.includes(i)?'':'off'}"></i>`).join('')}</div>`}
function spinner(segments=4, red=1, draggable=false){let paths='';const colors=['#df765a','#8eafa1'];for(let i=0;i<segments;i++){const a=i*2*Math.PI/segments-Math.PI/2,b=(i+1)*2*Math.PI/segments-Math.PI/2;const x=80+72*Math.cos(a),y=80+72*Math.sin(a),xx=80+72*Math.cos(b),yy=80+72*Math.sin(b);paths+=`<path d="M80 80 L${x} ${y} A72 72 0 0 1 ${xx} ${yy} Z" fill="${colors[i<red?0:1]}" stroke="#f4f4e7" stroke-width="2"/>`;const m=(a+b)/2;paths+=`<text x="${80+49*Math.cos(m)}" y="${84+49*Math.sin(m)}" text-anchor="middle" font-size="12" fill="#fff" font-family="sans-serif">${i+1}</text>`}return `<div class="spinner-wrap object" ${draggable?'data-drag tabindex="0" role="button" aria-label="Move spinner with arrow keys or drag"':''}><svg viewBox="0 0 160 160" role="img" aria-label="${segments} equal sectors, ${red} coral">${paths}<circle cx="80" cy="80" r="74" fill="none" stroke="#f8f6e9" stroke-width="5"/></svg><span class="spinner-arrow"></span></div>`}
function cover(){return `<div class="cover"><div class="cover-copy"><span class="pill"><span class="dot"></span> CHANCE ADVENTURE · مغامرة الاحتمالات</span><h1>Three worlds.<br><em>One adventure!</em></h1><div class="arabic-title ar" lang="ar">هيا نكتشف سرّ الاحتمال!</div><p>Coin. Spinner. Dice.<br>Play a little. Discover a lot.</p><button class="btn" data-action="navigate" data-slide="1">ابدئي المغامرة ← · Start</button></div><div class="cover-art"><div class="orbit"></div><span class="spark">✧</span>${coin('heads',true)}${die(5,true)}${spinner(4,1,true)}<div class="art-label">↔ DRAG TO EXPLORE</div></div></div><details class="cover-details"><summary>عن الدرس · About this lesson</summary><div class="credit-strip"><div><small>Prepared by · إعداد</small><strong>Walaa Falah</strong>${ar('ولاء فلاح')}</div><div><small>Professor · بإشراف</small><strong>Dr. Jehan Yousif</strong>${ar('د. جيهان يوسف')}</div><div><small>Teaching methods</small><strong>Micro-teaching task</strong>${ar('مهمة التدريس المصغر')}</div></div><div class="objective"><span class="symbol">◎</span><div><h3>Our learning goal · هدفنا التعليمي</h3><p>Given coins, dice, spinners, and practice tasks, Grade 9 students will calculate the probability of simple events with at least 80% accuracy.</p>${ar('باستخدام العملات والنرد والأقراص الدوارة والتدريبات، تحسب طالبات الصف التاسع احتمال الأحداث البسيطة بدقة لا تقل عن ٨٠٪.')}<div class="method-chips"><span>Guided inquiry</span><span>Think–pair–share</span><span>Game-based learning</span><span>Formative assessment</span></div></div><span class="pill green">80% mastery target</span></div></details>`}
function login(error=''){document.body.classList.remove('child-mode');
 clearIntervals();
 app.innerHTML=`<main class="entry"><section class="entry-story"><div class="kicker"><span class="logo-mark">◈</span><span class="logo">chance<em>studio.</em></span></div><div><div class="eyebrow">A LITTLE CURIOSITY. A WORLD OF POSSIBILITY.</div><h1>Every possibility<br>starts with<br><em>a question.</em></h1><p>Flip a dirham. Spin an idea. Discover the mathematics of everyday chance.</p>${ar('اقلبي درهماً، أطلقي فكرة، واكتشفي رياضيات الاحتمال.')}<div class="entry-objects">${coin()}${die()}${spinner()}</div></div><div class="entry-footer">WALAA FALAH &nbsp; / &nbsp; COIN · SPINNER · DICE</div></section><section class="entry-form"><div class="login-card"><div class="eyebrow">YOUR PROBABILITY CLASSROOM</div><h2>Let’s discover together.</h2>${ar('لنكتشف معاً')}<p>A lesson where every answer is a step forward.</p><div class="tabs" role="tablist"><button role="tab" aria-selected="${loginRole==='student'}" class="${loginRole==='student'?'active':''}" data-action="login-role" data-role="student">Student · طالبة</button><button role="tab" aria-selected="${loginRole==='teacher'}" class="${loginRole==='teacher'?'active':''}" data-action="login-role" data-role="teacher">Teacher · معلمة</button></div><form id="loginForm" class="stack">${loginRole==='student'?`<label class="field">Your name · اسم الطالبة<input name="name" placeholder="e.g. Mariam Ahmed" autocomplete="name" required minlength="2" maxlength="60"></label><label class="field">Class code · رمز الصف<input name="code" placeholder="Ask your teacher for the class code" required maxlength="30" autocomplete="off"></label>`:`<label class="field">Username · اسم المستخدم<input name="username" autocomplete="username" placeholder="Your teacher username" required></label><label class="field">Password · كلمة المرور<input name="password" type="password" autocomplete="current-password" required placeholder="Your password"></label>`}<div class="error" id="loginError" role="alert">${esc(error)}</div><button class="btn" type="submit">${loginRole==='teacher'?'Open teacher workspace':'Enter the classroom'} <span>→</span></button></form><div class="login-foot">${loginRole==='student'?'Your progress is saved in this classroom.<br>Use the same browser to continue your session.':'A live view of every learner. One connected classroom.'}</div></div></section></main>`;
 $('#loginForm').onsubmit=async e=>{e.preventDefault();const btn=$('button[type=submit]',e.target);btn.disabled=true;try{await api('login',{role:loginRole,...Object.fromEntries(new FormData(e.target))});await loadState();}catch(err){$('#loginError').textContent=err.message;btn.disabled=false}};
}
function clearIntervals(){clearInterval(timerInterval);clearInterval(monitorInterval);clearInterval(heartbeatInterval);clearInterval(videoInterval);if(player){try{player.destroy()}catch{}player=null}}
async function loadState(){state=await api('state');if(state.role==='student'){slide=state.student.slide||0;checkpointSeen=new Set(Object.keys(JSON.parse(state.student.video||'{}')));heartbeatInterval&&clearInterval(heartbeatInterval);heartbeatInterval=setInterval(()=>{saveProgress(false);pollClassroom()},5000)}renderShell();if(state.role==='teacher'){await refreshDashboard();monitorInterval&&clearInterval(monitorInterval);monitorInterval=setInterval(refreshDashboard,4000)}else{if(state.control?.mode==='teacher')slide=state.control.slide;renderSlide();addThinkingSpace();saveProgress(false);pollClassroom()}}
function renderShell(){const teacher=state.role==='teacher';document.body.classList.toggle('child-mode',!teacher);const name=teacher?'Walaa Falah':state.student.name;app.innerHTML=`<aside class="sidebar"><div class="kicker"><span class="logo-mark">◈</span><span class="logo">chance<em>studio.</em></span></div><div class="eyebrow">${teacher?'TEACHER WORKSPACE':'YOUR LEARNING JOURNEY'}</div><nav class="lesson-nav" aria-label="Lesson navigation">${teacher?['Live classroom','Video & questions','Lesson preview','Lesson plan','Class report'].map((t,i)=>`<button class="nav-step ${teacherTab===['monitor','video','preview','plan','report'][i]?'active':''}" data-action="teacher-tab" data-tab="${['monitor','video','preview','plan','report'][i]}"><span class="num">${['◉','▷','▤','✎','↗'][i]}</span><span><span class="nav-title">${t}</span>${ar(['متابعة مباشرة','الفيديو والأسئلة','معاينة الدرس','الخطة الدرسية','تقرير الصف'][i])}</span></button>`).join(''):steps.map((s,i)=>`<button class="nav-step ${slide===i?'active':''} ${visited(i)?'done':''}" data-action="navigate" data-slide="${i}" ${slide===i?'aria-current="step"':''}><span class="num">${visited(i)&&slide!==i?'✓':String(i+1).padStart(2,'0')}</span><span><span class="nav-title">${s[0]}</span>${ar(s[1])}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="teacher-note"><span class="eyebrow" style="margin:0">${teacher?'YOUR CLASS CODE':'A NOTE FROM MS. WALAA'}</span>${teacher?`<h2 style="font-size:22px;margin-top:9px;letter-spacing:2px">${esc(state.code)}</h2><p>Share this code with your students to join this classroom.</p>`:`<p>“Be curious. Make a prediction. Every try helps you grow.”</p>${ar('كل محاولة تقرّبك من الإتقان.','small')}`}</div><div class="profile"><span class="avatar">${esc(initials(name))}</span><div><strong>${esc(name)}</strong><small>${teacher?'Teacher · المعلمة':'Student · طالبة'}</small></div><button data-action="logout" aria-label="Sign out" title="Sign out">↪</button></div></div></aside><div class="workspace"><header class="topbar"><div><button class="icon-btn mobile-menu" data-action="menu" aria-label="Toggle navigation">☰</button><span class="breadcrumb">Chance adventure <span>/ &nbsp; Simple probability</span></span></div><div class="topbar-actions"><span class="pill green" id="syncStatus"><span class="dot"></span> ${teacher?'Live classroom':'Progress connected'}</span><button class="btn secondary small" data-action="print-lesson">▤ &nbsp; Print lesson</button></div></header><main class="main" id="content"></main></div>`;if(teacher)renderTeacher()}
function initials(n){return String(n).split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase()}
function visited(i){return JSON.parse(state?.student?.visited||'[]').includes(i)}
function slideHeading(i){return `<div class="page-heading"><div><div class="eyebrow">THE LEARNING JOURNEY &nbsp; / &nbsp; ${String(i+1).padStart(2,'0')}</div><h2>${steps[i][0]}</h2>${ar(steps[i][1])}</div><span class="pill">${steps[i][2]}</span></div>`}
function footer(){return `<footer class="lesson-footer"><button class="btn secondary" data-action="prev" ${slide===0?'disabled':''}>← السابق · Back</button><div class="row"><small>شريحة ${slide+1} / 8</small><div class="slide-dots">${steps.map((_,i)=>`<span class="${i===slide?'active':''}"></span>`).join('')}</div></div><button class="btn" data-action="next" ${slide===7?'disabled':''}>${slide===0?'ابدئي · Start':'التالي · Next'} →</button></footer>`}
function renderSlide(){stopPlayground();if(slide===2)restorePlayground();stopStudio();clearTimeout(autoResumeTimer);clearInterval(timerInterval);clearInterval(videoInterval);if(player){try{player.destroy()}catch{}player=null}$('#modal').hidden=true;activeCheckpoint=null;$('#content').innerHTML=slideHeading(slide)+`<section class="slide" id="slideContent">${[cover,videoSlide,reviewSlide,coinSlide,()=>gameSlide('race'),()=>gameSlide('mastery'),pollSlide,storySlide][slide]()}</section>`+footer();updateNav();enableDrag();if(slide===2&&state.role==='student')recordStory();updateAchievementRibbon();if(slide===1)initVideo();if(slide===4||slide===5){const mode=slide===4?'race':'mastery';activeGame=state.attempts.findLast?.(a=>a.mode===mode)||[...state.attempts].reverse().find(a=>a.mode===mode);gameFeedback=null;if(activeGame){activeGame.receivedAt=Date.now();renderGame();}if(mode==='race')refreshLeaderboard()}window.scrollTo({top:0,behavior:'instant'})}
function updateNav(){$$('.nav-step[data-slide]').forEach(b=>{let i=+b.dataset.slide;b.classList.toggle('active',i===slide);b.classList.toggle('done',visited(i));$('.num',b).textContent=visited(i)&&i!==slide?'✓':String(i+1).padStart(2,'0');if(i===slide)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')})}
async function navigate(i, teacherMove=false){if(state.control?.mode==='teacher'&&!teacherMove&&i!==state.control.slide){toast('Your teacher is guiding this slide. You can explore freely in student-paced mode.');return}await saveWork();slide=Math.max(0,Math.min(7,i));const sample=(state.samples||[]).find(w=>w.slide===slide);state.work={...state.work,reasoning:sample?.reasoning||'',strokes:sample?.strokes||'[]'};addThinkingSpace();const visitedList=JSON.parse(state.student.visited||'[]');if(!visitedList.includes(slide))visitedList.push(slide);state.student.visited=JSON.stringify(visitedList);renderSlide();await saveProgress(false)}
async function saveProgress(showError=true){if(!state||state.role!=='student')return;try{await api('progress',{slide});linked=true;syncStatus()}catch(e){linked=false;syncStatus();if(showError)toast(e.message)}}
function syncStatus(){const el=$('#syncStatus');if(el){el.className='pill '+(linked?'green':'coral');el.innerHTML=`<span class="dot"></span> ${linked?'Progress connected':'Reconnecting…'}`}}
function reviewSlide(){return playgroundHTML()+`<details class="story-resources"><summary>📖 المزيد عند الحاجة · Help & review</summary><details class="guide-details"><summary>▷ Watch a worked example · شاهدي مثالاً محلولاً خطوة بخطوة</summary>${studioHTML()}</details><details class="guide-details"><summary>▤ My pocket revision card · بطاقة المراجعة</summary><div class="card"><div class="row spread"><div><div class="eyebrow">KEEP THIS IDEA WITH YOU</div><h2 style="margin-top:10px">Count the possibilities.</h2>${ar('عدّي النواتج الممكنة')}</div><span class="pill gold">Your revision card</span></div><div class="math">\\(P(E)=\\frac{n(E)}{n(S)},\\quad 0\\le P(E)\\le 1\\)</div><div class="formula"><b>P(event) =</b><div class="fraction"><span>Number of favorable outcomes${ar('عدد النواتج المرغوبة')}</span><span>Total number of equally likely outcomes${ar('عدد النواتج الكلي المتساوية الاحتمال')}</span></div></div><div class="grid3"><div class="tool-card">${coin('heads',true)}<h3>A fair coin · عملة عادلة</h3><p>2 outcomes · P(heads) = 1/2</p>${ar('وجهان متساويا الاحتمال','small')}</div><div class="tool-card">${die(5,true)}<h3>A fair die · نرد عادل</h3><p>6 outcomes · P(5) = 1/6</p>${ar('ستة نواتج متساوية الاحتمال','small')}</div><div class="tool-card">${spinner(4,1,true)}<h3>An equal spinner · قرص عادل</h3><p>4 sectors · P(coral) = 1/4</p>${ar('أربعة قطاعات متساوية','small')}</div></div><div class="prob-scale"><span><b>0</b>Impossible${ar('مستحيل','small')}</span><span><b>1/2</b>Even chance${ar('فرصتان متساويتان','small')}</span><span><b>1</b>Certain${ar('مؤكد','small')}</span></div><div class="lesson-note">✧ The denominator counts <strong>all equally likely outcomes</strong>. The numerator counts the outcomes you want.${ar('المقام يحصي جميع النواتج المتساوية الاحتمال، والبسط يحصي النواتج المرغوبة.','small')}</div><div class="row" style="justify-content:center;margin-top:18px"><button class="btn secondary small" data-action="spin">↻ Try the spinner</button><button class="btn secondary small" data-action="roll">⚄ Roll the die</button><a class="btn ghost small" href="dice-lab.html" target="_blank" rel="noopener">Open dice lab ↗</a></div><p id="exploreResult" class="subtle" style="font-size:11px;text-align:center;margin-top:12px" aria-live="polite">Drag the objects, or select one and use arrow keys. / اسحبي الأشكال أو استخدمي الأسهم.</p></div></details></details>`}
function videoSlide(){let l=state.lesson;return `<div class="video-layout"><div><div class="video-screen">${l.videoId?'<div id="youtubePlayer"></div><section id="videoQuestion" class="video-question" hidden aria-label="Video question"></section>':`<div class="video-empty"><div class="play">▷</div><div class="eyebrow" style="color:#a9c5b5">WATCH. PAUSE. THINK.</div><h3 style="margin-top:12px">A little wonder is on its way.</h3><p>Your teacher will add the lesson video here.<br>You can continue to the review card while it’s being prepared.</p>${ar('ستضيف المعلمة الفيديو هنا. يمكنك متابعة بطاقة المراجعة.','small')}</div>`}</div><div class="video-caption"><p>${l.videoId?'Watch closely. The video pauses for your questions.':'No video has been assigned yet.'}${ar('شاهدي وفكري ثم اختاري إجابتك.','small')}</p><button class="btn secondary small" data-action="video-help">Playback help</button></div><div class="lesson-note" id="videoStatus" style="margin-top:16px">${l.videoId?'Press play once. Questions appear here automatically; choose your answer directly on the video. / اضغطي تشغيل مرة واحدة، ثم أجيبي مباشرة داخل الفيديو.':'Video progress will appear here once your teacher adds a video.'}</div></div><aside class="card video-aside"><div class="eyebrow">THINKING STOPS</div><h3 style="margin-top:10px">Questions inside the video.</h3>${ar('أسئلة تظهر تلقائياً داخل الفيديو','small')}<div class="checkpoint-list">${l.checkpoints.length?l.checkpoints.map((c,i)=>`<div class="checkpoint-item"><span class="time-tag">${formatTime(c.at)}</span><div><strong>Checkpoint ${i+1} ${checkpointSeen.has(c.id)?'✓':''}</strong><p style="font-size:10px;color:var(--muted);margin-top:5px">${esc(c.en)}</p></div></div>`).join(''):`<div class="empty" style="margin-top:20px;padding:20px"><p>No questions added yet.${ar('لا توجد أسئلة بعد','small')}</p></div>`}</div><div class="divider"></div><p style="font-size:10px;color:var(--muted)">Your first answer at each checkpoint is saved to your teacher’s dashboard.</p></aside></div>`}
function formatTime(s){return `${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`}
function initVideo(){if(!state.lesson.videoId)return;if(window.YT?.Player)mountVideo();else{if(!$('#youtubeAPI')){let script=document.createElement('script');script.id='youtubeAPI';script.src='https://www.youtube.com/iframe_api';script.onerror=()=>videoError();document.head.appendChild(script)}window.onYouTubeIframeAPIReady=mountVideo;setTimeout(()=>{if(slide===1&&!player)videoError()},10000)}}
function videoError(){if($('#videoStatus'))$('#videoStatus').innerHTML='The video provider could not load. Check the internet connection and embedding permissions. Your progress in the rest of the lesson is safe. '+ar('تعذر تحميل الفيديو. تحققي من الاتصال والسماح بتضمين الفيديو.','small')}
function mountVideo(){if(slide!==1||!$('#youtubePlayer'))return;player=new YT.Player('youtubePlayer',{videoId:state.lesson.videoId,host:'https://www.youtube.com',playerVars:{playsinline:1,rel:0,fs:0,start:state.lesson.start||0,end:state.lesson.end||7200,origin:location.origin},events:{onReady:()=>{$('#videoStatus').textContent='Ready when you are. Press play to start. / اضغطي تشغيل للبدء.';videoInterval=setInterval(checkVideo,350)},onError:videoError,onStateChange:()=>{if(activeCheckpoint&&player?.pauseVideo)player.pauseVideo()}}})}
function checkVideo(){if(!player?.getCurrentTime||activeCheckpoint)return;const raw=player.getCurrentTime(),start=state.lesson.start||0,end=state.lesson.end||7200;if(raw<start){player.seekTo?.(start,true);return}const t=raw-start;const cp=state.lesson.checkpoints.find(c=>!checkpointSeen.has(c.id)&&t>=c.at);if(cp){player.pauseVideo();player.seekTo?.(start+cp.at,true);showCheckpoint(cp);return}if(raw>=end){player.pauseVideo();player.seekTo?.(end,true);if($('#videoStatus'))$('#videoStatus').textContent='Segment complete · اكتمل المقطع (00:08–04:18).';}}
function showCheckpoint(cp){activeCheckpoint=cp;const panel=$('#videoQuestion');panel.hidden=false;$('.video-screen').classList.add('answering');panel.innerHTML=`<div class="video-question-content"><span class="pill coral">Video paused automatically · توقف الفيديو تلقائياً · ${formatTime(cp.at)}</span><h2 id="checkpointTitle">${esc(cp.en)}</h2>${ar(cp.ar)}<div class="options">${cp.options.map((o,i)=>`<button class="option" data-action="video-answer" data-choice="${i}"><span class="letter">${'ABCD'[i]}</span>${esc(o)}</button>`).join('')}</div><div id="checkpointFeedback" aria-live="polite"></div></div>`;panel.scrollTop=0;$('.option',panel).focus({preventScroll:true});panel.scrollIntoView({block:'nearest',behavior:'smooth'})}
let autoResumeTimer=null;
async function answerCheckpoint(choice){if(!activeCheckpoint)return;const checkpointId=activeCheckpoint.id;$$('.option',$('#videoQuestion')).forEach(b=>b.disabled=true);try{const result=await api('video-answer',{id:activeCheckpoint.id,choice});if(activeCheckpoint?.id!==checkpointId||!$('#videoQuestion'))return;checkpointSeen.add(activeCheckpoint.id);const record=JSON.parse(state.student.video||'{}');record[activeCheckpoint.id]={choice,correct:result.correct};state.student.video=JSON.stringify(record);$('#checkpointFeedback').innerHTML=`<div class="feedback ${result.correct?'':'wrong'}">${result.correct?'✓ Well reasoned!':'Keep learning. The correct answer is: '+esc(activeCheckpoint.options[result.answer])}${ar(result.correct?'أحسنتِ التفكير!':'الإجابة الصحيحة موضحة أعلاه.','small')}<p dir="auto">${esc(result.explanation||'Compare the selected outcome with the question, count the equally likely possibilities, then identify the favorable outcomes. / حددي المطلوب، ثم عدّي النواتج الكلية المتساوية الاحتمال والنواتج المرغوبة.')}</p></div><button class="btn" style="margin-top:18px" data-action="video-continue">Continue video →</button>`;$$('.option',$('#videoQuestion')).forEach((b,i)=>b.classList.toggle('correct',i===result.answer));const feedback=$('#checkpointFeedback').innerHTML;$('#videoStatus').innerHTML=feedback.replace(/<button[\s\S]*?<\/button>/g,'');$('#checkpointFeedback').insertAdjacentHTML('beforeend','<p>Auto-resume in 12 seconds. The explanation stays below the video. / استئناف تلقائي بعد ١٢ ثانية، ويبقى الشرح أسفل الفيديو.</p><button class="btn secondary small" data-action="hold-video">More reading time · وقت إضافي للقراءة</button>');$('#checkpointFeedback').scrollIntoView({block:'nearest',behavior:'smooth'});autoResumeTimer=setTimeout(continueVideo,12000)}catch(e){toast(e.message);$$('.option',$('#videoQuestion')).forEach(b=>b.disabled=false)}}
function coinSlide(){return `<div class="question-card card"><span class="pill coral">01 QUICK CHECK · تحقق سريع</span><h2 style="margin-top:20px">One dirham. Two possibilities.</h2>${ar('درهم واحد، نتيجتان محتملتان')}<p class="subtle" style="font-size:12px;margin-top:12px">We define “heads” as the dallah (coffee pot) face. For a fair dirham, both faces are equally likely.</p>${ar('نعدّ وجه الدلة هو الوجه المطلوب. في الدرهم العادل، الوجهان متساويا الاحتمال.','small')}<div class="coin-stage"><div class="coin-pair"><div>${coin('heads',true)}<p><b>Heads · وجه الدلة</b></p></div><span class="subtle">or</span><div>${coin('tails',true)}<p><b>Tails · وجه الرقم</b></p></div></div><p class="note">Stylized UAE 1-dirham illustrations · رسوم توضيحية لوجهي الدرهم الإماراتي</p></div><div class="row spread"><div><h3>What is P(heads) on one flip?</h3>${ar('ما احتمال ظهور وجه الدلة عند قلب الدرهم مرة واحدة؟','small')}</div><button class="btn secondary small" data-action="flip">↻ Flip</button></div><p id="flipResult" class="subtle" style="font-size:11px;margin-top:12px" aria-live="polite">Predict before you flip. / توقعي قبل القلب.</p><div class="options">${['1/4','1/2','1','0'].map((x,i)=>`<button class="option" data-action="coin-answer" data-choice="${i}"><span class="letter">${'ABCD'[i]}</span>${x}</button>`).join('')}</div><div id="coinFeedback" aria-live="polite">${state.student.coin!==null?`<div class="feedback ${state.student.coin?'':'wrong'}">${state.student.coin?'✓ Your last answer was correct: P(heads) = 1/2.':'Your last answer needs another look. There is 1 favorable outcome out of 2.'}${ar('احتمال ظهور وجه الدلة = ١ ÷ ٢ = ١/٢.','small')}</div>`:''}</div></div>`}
function gameSlide(mode){return `<div class="game-area"><div id="gamePanel">${gameIntro(mode)}</div><aside class="card leader-card">${mode==='race'?`<div class="leader-heading"><h3>Class leaderboard</h3><span class="pill green" style="font-size:8px">LIVE</span></div>${ar('لوحة المتصدرات','small')}<div id="leaderboard"><p class="subtle" style="font-size:11px;margin-top:15px">Waiting for the first player…</p></div>`:`<div class="eyebrow">PROGRESS OVER PERFECTION</div><h3 style="margin:13px 0">Make it yours.</h3>${ar('رحلتك نحو الإتقان','small')}<div class="rule-list"><div><b>01</b><span>12 questions drawn from a larger question bank.</span></div><div><b>02</b><span>Coins, dice, and equal-sector spinners only.</span></div><div><b>03</b><span>10 correct answers = 83.3%. That reaches our 80% goal.</span></div><div><b>04</b><span>Review your answers and try a fresh set if needed.</span></div></div>`}</aside></div>`}
function gameIntro(mode){return `<div class="game-intro"><div><span class="pill ${mode==='race'?'coral':'green'}">${mode==='race'?'ROUND 01 · CLASS CHALLENGE':'ROUND 02 · PERSONAL MASTERY'}</span><h2>${mode==='race'?'A little speed.<br>A lot of thinking.':'Your next level<br>starts here.'}</h2><p>${mode==='race'?'Make your prediction, beat the clock, and climb the class leaderboard. Every correct answer counts.':'A fresh selection of questions, a clear goal, and another chance to grow. Aim for at least 10 correct answers.'}</p>${ar(mode==='race'?'توقعي، سابقي الوقت، وتقدمي في لوحة المتصدرات.':'تدربي على أسئلة متنوعة. أجيبي عن ١٠ أسئلة صحيحة على الأقل للإتقان.')}<div class="game-specs"><div><b>${mode==='race'?10:12}</b><span>QUESTIONS · سؤال</span></div><div><b>40<span style="font-size:15px">s</span></b><span>EACH · لكل سؤال</span></div><div><b>${mode==='race'?'200':'80%'}</b><span>${mode==='race'?'MAX PTS / ANSWER':'MASTERY TARGET'}</span></div></div><p>${mode==='race'?'100 points for a correct answer + up to 100 speed points. One competition attempt per student.':'No competition here. Your best mastery attempt is included in your learning report.'}</p><button class="btn" data-action="start-game" data-mode="${mode}">Start ${mode==='race'?'the sprint':'my quest'} →</button><p style="font-size:10px;margin-top:14px">The clock starts when you begin. It keeps running if you leave.${ar('يستمر الوقت إذا غادرتِ اللعبة.','small')}</p></div><div class="game-art"><span class="trophy">${mode==='race'?'♜':'✦'}</span>${coin()}${die(5)}</div></div>`}
function storeAttempt(a){a.receivedAt=Date.now();const idx=state.attempts.findIndex(x=>x.id===a.id);if(idx===-1)state.attempts.push(a);else state.attempts[idx]=a;activeGame=a}
async function startGame(mode){try{const a=await api('start',{mode});storeAttempt(a);gameFeedback=null;renderGame();refreshLeaderboard()}catch(e){toast(e.message)}}
function questionVisual(q){if(q.visual==='coin')return `<div class="coin-pair"><div>${coin('heads')}<p class="visual-label">Dallah / heads</p></div><div>${coin('tails')}<p class="visual-label">Value / tails</p></div></div>`;if(q.visual==='spinner')return spinner(q.detail.segments,q.detail.red);if(q.visual==='numbered')return spinner(q.detail.startsWith('1, 2, 3, 4, 5')?8:4,0);return die(5)}
function renderGame(){if(!$('#gamePanel')||!activeGame)return;clearInterval(timerInterval);let a=activeGame;if(a.waiting&&!a.finished){const q=a.responses.at(-1);$('#gamePanel').innerHTML='<div class="card"><h2>Let’s understand the answer · لنفهم الحل</h2>'+workedSolution(q)+'<button class="btn" data-action="resume-game">I understand — next question · فهمت، التالي →</button><p class="subtle">The next timer starts when you continue. / يبدأ وقت السؤال التالي بعد المتابعة.</p></div>';quizBusy=false;return}if(a.finished){$('#gamePanel').innerHTML=gameResult(a);return}const q=a.question;$('#gamePanel').innerHTML=`<div class="quiz-top"><div><div class="eyebrow">${a.mode==='race'?'PROBABILITY SPRINT':'MASTERY QUEST'}</div><h3 style="margin-top:7px">Question ${a.index+1} <span class="subtle" style="font-size:13px;font-weight:400">of ${a.total}</span></h3></div><div class="row"><span class="pill gold">${a.points} pts</span><div class="timer" id="timer" role="timer" aria-label="Seconds remaining">◷ <span>40</span></div></div></div><div class="progress-track"><div style="width:${a.index/a.total*100}%"></div></div><div class="card question-card"><span class="eyebrow">${esc(q.kind)} · SIMPLE EVENTS</span><h2 style="margin-top:13px">${esc(q.en)}</h2>${ar(q.ar)}<div class="question-visual">${questionVisual(q)}</div><p class="visual-label">${typeof q.detail==='string'?esc(q.detail):`${q.detail.segments} equal sectors · ${q.detail.red} coral / قطاعات متساوية`}</p><div class="options">${q.choices.map((c,i)=>`<button class="option" data-action="game-answer" data-choice="${i}"><span class="letter">${'ABCD'[i]}</span>${esc(c)}</button>`).join('')}</div><div id="gameSaveError" class="error" role="alert" style="margin-top:12px"></div></div><div id="lastFeedback" aria-live="polite">${gameFeedback?feedbackHTML(gameFeedback):''}</div><p class="subtle" style="font-size:10px;text-align:center;margin-top:16px">Your answer saves automatically. The next question starts immediately.${ar('تُحفظ إجابتك تلقائياً ويبدأ السؤال التالي مباشرة.','small')}</p>`;quizBusy=false;updateTimer();timerInterval=setInterval(updateTimer,250)}
function feedbackHTML(f){if(f.expired)return `<div class="feedback wrong">Time’s up. Unanswered questions count as incorrect. Keep going!${ar('انتهى الوقت. الأسئلة غير المجابة تُحسب خطأ. تابعي!','small')}</div>`;return `<div class="feedback ${f.correct?'':'wrong'}"><b>${f.correct?'✓ Correct! +'+f.points+' points':'The answer was '+esc(f.answer)+'. Keep going.'}</b><br>${esc(f.explanation)}${ar(f.explanationAr,'small')}${f.worked?workedSolution(f.worked):''}</div>`}
function updateTimer(){if(!activeGame||activeGame.finished||!$('#timer'))return;const offset=activeGame.serverNow-activeGame.receivedAt;const left=Math.max(0,Math.ceil((activeGame.deadline-(Date.now()+offset))/1000));$('#timer span').textContent=left;$('#timer').classList.toggle('urgent',left<=10);if(left===0&&!quizBusy)answerGame(null)}
async function answerGame(choice){if(quizBusy||!activeGame)return;quizBusy=true;$$('#gamePanel .option').forEach(b=>b.disabled=true);try{let r=await api('answer',{attempt:activeGame.id,index:activeGame.index,choice});r.attempt.receivedAt=Date.now();storeAttempt(r.attempt);gameFeedback=r.feedback;renderGame();refreshLeaderboard()}catch(e){quizBusy=false;const el=$('#gameSaveError');if(el)el.innerHTML=`${esc(e.message)} <button class="btn small secondary" data-action="retry-game">Reconnect</button>`;$$('#gamePanel .option').forEach(b=>b.disabled=false);clearInterval(timerInterval);toast('Answer was not saved. Reconnect to continue.')}}
function gameResult(a){return `<section class="card result"><div class="result-symbol">${a.mastered?'✦':'◈'}</div><span class="eyebrow">${a.mode==='race'?'SPRINT COMPLETE':'QUEST COMPLETE'}</span><h2>${a.mastered?'Look how far you’ve come.':'Every try moves you forward.'}</h2>${ar(a.mastered?'أحسنتِ! لقد حققتِ هدف الإتقان.':'كل محاولة تقرّبك من الإتقان.')}<p>${a.mode==='race'?'Your score is on the class leaderboard.':a.mastered?'You reached the 80% mastery goal.':'You need 10 out of 12 correct. Review the feedback, then try a fresh set.'}</p><div class="score-row"><div><b>${a.correct}/${a.total}</b><span>CORRECT · صحيح</span></div><div><b>${a.percent}%</b><span>ACCURACY · الدقة</span></div><div><b>${a.points}</b><span>POINTS · نقاط</span></div></div>${a.responses?.at(-1)&&!a.responses.at(-1).correct?workedSolution(a.responses.at(-1)):''}${a.mode==='mastery'?`<button class="btn" data-action="start-game" data-mode="mastery">${a.mastered?'Try another set':'Practice again'} ↻</button>`:`<button class="btn" data-action="navigate" data-slide="5">Continue to mastery →</button>`}<details style="text-align:left;margin-top:25px"><summary>Review my ${a.total} answers · مراجعة إجاباتي</summary>${(a.review||[]).map((q,i)=>`<div class="review-item"><b>${q.correct?'✓':'✕'} ${i+1}. ${esc(q.en)}</b>${ar(q.ar)}<p>Your answer: ${q.choice===null?'Time expired':esc(q.choices[q.choice])} · Correct: ${esc(q.choices[q.correctAnswer])}</p>${workedSolution(q)}</div>`).join('')}</details></section>`}
async function refreshLeaderboard(){if(state?.role!=='student'||slide!==4)return;try{const d=await api('leaderboard');if($('#leaderboard'))$('#leaderboard').innerHTML=d.leaders.length?d.leaders.map((l,i)=>`<div class="leader-row ${l.me?'me':''}"><span class="rank">${String(i+1).padStart(2,'0')}</span><span class="name">${esc(l.name)}${l.me?' (you)':''}<br><small>${l.answered}/10 answered</small></span><strong>${l.points}</strong></div>`).join(''):'<p class="subtle" style="font-size:11px;margin-top:20px">Be the first to start the sprint.</p>'}catch{}}
function pollSlide(){return `<div class="card question-card"><span class="pill green">EXIT TICKET · بطاقة الخروج</span><h2 style="margin-top:22px">How does probability feel now?</h2>${ar('ما مدى فهمك للاحتمالات الآن؟')}<p style="font-size:12px;margin-top:15px;color:var(--muted)">There’s no wrong answer here. Your response helps Ms. Walaa plan what comes next.</p><div class="poll-options">${POLLS.map((p,i)=>`<button class="poll-option ${state.student.poll===i?'selected':''}" data-action="poll" data-choice="${i}" aria-pressed="${state.student.poll===i}"><span class="emoji">${p[2]}</span><strong>${p[0]}</strong>${ar(p[1])}</button>`).join('')}</div><div id="pollFeedback" aria-live="polite">${state.student.poll!==null?'<div class="feedback">✓ Your reflection is saved. Thank you for sharing! '+ar('تم حفظ رأيك. شكراً لمشاركتك!','small')+'</div>':''}</div><div class="lesson-note" style="margin-top:20px">Before you go: explain to a partner why P(heads) = 1/2. What changes if a spinner has unequal sectors?${ar('قبل المغادرة: اشرحي لزميلتك لماذا احتمال وجه الدلة هو ١/٢. ماذا يتغير إذا كانت قطاعات القرص غير متساوية؟','small')}</div></div>`}
function bestAttempt(mode){return state.attempts.filter(a=>a.mode===mode&&a.finished).sort((a,b)=>b.percent-a.percent||b.points-a.points)[0]}
function storySlide(){const race=bestAttempt('race'),mastery=bestAttempt('mastery'),v=JSON.parse(state.student.video||'{}');return `<div class="card"><div class="row spread"><div><div class="eyebrow">A LITTLE REFLECTION. A LOT OF GROWTH.</div><h2 style="margin-top:12px">${esc(state.student.name)}, this is your learning story.</h2>${ar('هذه رحلتك التعليمية')}</div><span style="font-size:40px;color:var(--gold)">✦</span></div>${achievementHTML()}<div class="stat-grid" style="margin-top:25px"><div class="stat"><small>Slides explored</small><b>${JSON.parse(state.student.visited).length}/8</b><span>الشرائح المستكشفة</span></div><div class="stat"><small>Video checkpoints</small><b>${Object.keys(v).length}/${state.lesson.checkpoints.length}</b><span>أسئلة الفيديو المجابة</span></div><div class="stat"><small>Sprint accuracy</small><b>${race?race.percent+'%':'—'}</b><span>${race?race.points+' points':'Not completed yet'}</span></div><div class="stat"><small>Best mastery score</small><b>${mastery?mastery.percent+'%':'—'}</b><span>${mastery?(mastery.mastered?'Goal achieved ✓':'Keep practicing'):'Not completed yet'}</span></div></div><div class="grid2"><div class="lesson-note"><h3 style="font-size:14px;margin-bottom:9px">Your next step</h3>${mastery?.mastered?'You reached our goal. Try explaining a spinner question to a friend.':"Keep practicing. Revisit the big idea, count all outcomes, and try the mastery quest again."}${ar(mastery?.mastered?'لقد حققتِ الهدف. حاولي شرح مسألة عن القرص لزميلتك.':'راجعي الفكرة الأساسية ثم حاولي رحلة الإتقان مرة أخرى.','small')}</div><div class="lesson-note"><h3 style="font-size:14px;margin-bottom:9px">Your voice</h3>${state.student.poll!==null?esc(POLLS[state.student.poll][0]):'You haven’t shared your exit reflection yet.'}${ar(state.student.poll!==null?POLLS[state.student.poll][1]:'لم تشاركي رأيك الختامي بعد.','small')}</div></div><div class="row" style="margin-top:25px;flex-wrap:wrap"><button class="btn" data-action="print-progress">Print my progress ▤</button><button class="btn secondary" data-action="print-lesson">Print lesson materials</button><button class="btn ghost" data-action="navigate" data-slide="5">Back to practice →</button></div></div>`}
/* Teacher workspace */
function renderTeacher(){if(state.role!=='teacher')return;const tabs=[['monitor','Live classroom'],['video','Video & questions'],['preview','Lesson preview'],['plan','Lesson plan'],['report','Class report']];$('#content').innerHTML=`<div class="page-heading"><div><div class="eyebrow">WALAA’S TEACHER WORKSPACE</div><h2>${tabs.find(t=>t[0]===teacherTab)[1]}</h2>${ar('كل طالبة، كل خطوة، في مكان واحد')}</div><span class="pill green"><span class="dot"></span> <span id="dashboardStatus">Syncing…</span></span></div><div class="teacher-tabs">${tabs.map(t=>`<button data-action="teacher-tab" data-tab="${t[0]}" class="${teacherTab===t[0]?'active':''}">${t[1]}</button>`).join('')}</div><div id="teacherPanel"></div>`;if(teacherTab==='video')renderVideoEditor();else if(teacherTab==='preview')renderPreview();else if(teacherTab==='plan')renderPlan();else if(dashboard)renderDashboardPanel();else $('#teacherPanel').innerHTML='<div class="loading">Loading classroom…</div>';$$('.nav-step[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===teacherTab))}
async function refreshDashboard(){if(state?.role!=='teacher')return;try{dashboard=await api('dashboard');state.control=dashboard.control;state.lesson=dashboard.lesson;if($('#dashboardStatus'))$('#dashboardStatus').textContent='Updated '+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'});if(teacherTab==='monitor'||teacherTab==='report')renderDashboardPanel();if(selectedStudent)refreshStudentView()}catch(e){if($('#dashboardStatus'))$('#dashboardStatus').textContent='Disconnected · retrying';}}
function summary(){const students=dashboard.students, attempts=dashboard.attempts;return {joined:students.length,active:students.filter(s=>Date.now()/1000-s.seen<35).length,mastered:students.filter(s=>attempts.some(a=>a.student===s.id&&a.mode==='mastery'&&a.mastered)).length,help:(dashboard.work||[]).filter(w=>w.help).length,polls:students.filter(s=>s.poll!==null).length}}
function studentStats(s){let a=dashboard.attempts.filter(a=>a.student===s.id);const race=a.find(a=>a.mode==='race');const mastery=a.filter(a=>a.mode==='mastery'&&a.finished).sort((x,y)=>y.percent-x.percent)[0];const current=a.filter(a=>!a.finished).at(-1);let w=(dashboard.work||[]).find(w=>w.student===s.id)||{};return {race,mastery,current,work:w,video:JSON.parse(s.video),visited:JSON.parse(s.visited)}}
function statsHTML(){const d=summary();return `<div class="stat-grid"><div class="stat"><small>Students in class · الطالبات</small><b>${d.joined}<span style="font-size:13px;color:var(--muted)"> / ${d.active} live</span></b><span>Connected in the last 35 seconds</span></div><div class="stat"><small>Mastery achieved · الإتقان</small><b>${d.joined?Math.round(d.mastered/d.joined*100):0}%</b><span>${d.mastered} reached at least 80%</span></div><div class="stat"><small>Hands raised · طلبات المساعدة</small><b>${d.help}</b><span>Ready for your support</span></div><div class="stat"><small>Exit reflections · الآراء الختامية</small><b>${d.polls}<span style="font-size:13px;color:var(--muted)"> / ${d.joined}</span></b><span>Student confidence, in their words</span></div></div>`}
function controlsHTML(){let c=state.control||{mode:'student',slide:0};return `<div class="class-control"><div><div class="eyebrow">YOU SET THE PACE</div><h3 style="font-size:15px;margin-top:7px">${c.mode==='student'?'Students explore at their own pace':'You’re guiding the lesson'}</h3></div><div class="row" style="flex-wrap:wrap"><button class="btn ${c.mode==='student'?'':'secondary'} small" data-action="pace" data-mode="student">Student-paced</button><button class="btn ${c.mode==='teacher'?'':'secondary'} small" data-action="pace" data-mode="teacher">Teacher-led</button><label class="field" style="min-width:160px"><span class="sr-only">Teacher-led slide</span><select id="controlSlide" aria-label="Teacher-led slide" ${c.mode==='student'?'disabled':''}>${steps.map((s,i)=>`<option value="${i}" ${c.slide===i?'selected':''}>${i+1}. ${s[0]}</option>`).join('')}</select></label></div></div>`}
let galleryMode=true, selectedStudent=null;
function renderDashboardPanel(){if(!dashboard)return;if(teacherTab==='report'){$('#teacherPanel').innerHTML=reportHTML()+`<div class="row" style="margin:24px 0"><button class="btn" data-action="print-report">Print full class report ▤</button><button class="btn secondary" data-action="export-csv">Export student results ↓</button></div>`;return}$('#teacherPanel').innerHTML=controlsHTML()+labMonitor()+missionControl()+statsHTML()+diagnosticHTML()+`<div class="card"><div class="row spread" style="margin-bottom:20px;flex-wrap:wrap"><div><h3>Every learner, in view.</h3><p class="subtle" style="font-size:11px;margin-top:5px">Open a student’s work to review answers and send private feedback.</p></div><div class="row"><button class="btn secondary small" data-action="view-mode">${galleryMode?'☷ Table view':'▦ Work gallery'}</button><span class="pill">Join code <strong>${esc(state.code)}</strong></span></div></div>${dashboard.students.length?(galleryMode?workGallery():studentTable()):`<div class="empty"><div style="font-size:35px;color:var(--teal)">◎</div><h3 style="margin-top:12px">A classroom full of possibilities.</h3><p>Ask students to open this app and join with <strong>${esc(state.code)}</strong>.<br>Real student progress will appear here. No demo data.</p>${ar('ستظهر هنا متابعة الطالبات بعد انضمامهن.','small')}</div>`}</div><div class="dashboard-bottom"><div class="card"><h3 style="font-size:16px">The room’s reflection</h3>${ar('صوت الطالبات','small')}<div style="margin-top:20px">${POLLS.map((p,i)=>{let n=dashboard.students.filter(s=>s.poll===i).length;return `<div class="row" style="margin:16px 0;gap:10px"><span style="font-size:16px;width:20px">${p[2]}</span><span style="font-size:10px;width:128px">${p[0]}</span><div class="poll-stats"><i style="width:${dashboard.students.length?n/dashboard.students.length*100:0}%"></i></div><b style="font-size:11px">${n}</b></div>`}).join('')}</div></div><div class="card"><div class="eyebrow">TEACHING TOOLKIT</div><h3 style="margin-top:10px">More than one way to learn.</h3><div class="rule-list"><div><b>◎</b><span><strong>Predict–observe–explain</strong><br>Ask for a coin prediction, test it, then discuss fairness.</span></div><div><b>↔</b><span><strong>Think–pair–share</strong><br>Let partners explain why equal sectors matter.</span></div><div><b>✎</b><span><strong>Make thinking visible</strong><br>Students sketch outcomes in their thinking space. Use the gallery to spot misconceptions.</span></div><div><b>✦</b><span><strong>Differentiate</strong><br>Send individual feedback. Invite students who need support back to the review card.</span></div></div></div></div>`;if(galleryMode)$$('canvas[data-student]').forEach(c=>{let w=dashboard.work.find(w=>w.student===c.dataset.student);paintStrokes(c,JSON.parse(w?.strokes||'[]'))});$('#controlSlide')?.addEventListener('change',e=>setPace('teacher',+e.target.value))}
function studentTable(report=false){return `<div class="table-wrap"><table><thead><tr><th>Student</th><th>Journey</th><th>Video</th><th>Dirham</th><th>Sprint</th><th>Mastery · best</th><th>Reflection</th>${report?'':'<th>Work</th>'}</tr></thead><tbody>${dashboard.students.map(s=>{let d=studentStats(s);return `<tr><td><div class="student-name"><span class="avatar">${esc(initials(s.name))}</span><span>${esc(s.name)}${!report?`<br><small>${Date.now()/1000-s.seen<35?'● Live':'Away'}${d.work.help?' · ✋ Help requested':''}</small>`:''}</span></div></td><td>${d.visited.length}/8 explored<br><small>${esc(steps[s.slide]?.[0]||'Welcome')}</small><div class="mini-progress"><i style="width:${d.visited.length/8*100}%"></i></div></td><td>${Object.keys(d.video).length}/${dashboard.lesson.checkpoints.length}<br><small>${Object.values(d.video).filter(x=>x.correct).length} correct</small></td><td>${s.coin===null?'—':s.coin?'✓ Correct':'Needs review'}</td><td>${d.race?`${d.race.points} pts<br><small>${d.race.index}/10 answered · ${d.race.finished?d.race.percent+'%':'In progress'}</small>`:'—'}</td><td>${d.mastery?`<span class="pill ${d.mastery.mastered?'green':'gold'}">${d.mastery.percent}%</span><br><small>${d.mastery.correct}/12 correct</small>`:d.current?.mode==='mastery'?`In progress<br><small>${d.current.index}/12 answered</small>`:'—'}</td><td>${s.poll===null?'—':esc(POLLS[s.poll][0])}</td>${report?'':`<td><button class="btn secondary small" data-action="student-detail" data-id="${esc(s.id)}">Review ${d.work.help?'✋':'↗'}</button></td>`}</tr>`}).join('')}</tbody></table></div>`}
function workGallery(){return `<div class="work-gallery">${dashboard.students.map(s=>{let d=studentStats(s);return `<button class="work-tile" data-action="student-detail" data-id="${esc(s.id)}"><div class="row spread"><strong>${esc(s.name)}</strong><span class="pill ${d.work.help?'coral':'green'}">${d.work.help?'✋ Help':'Slide '+(s.slide+1)}</span></div>${slideThumbnail(s)}${progressBubbles(s)}<canvas width="400" height="200" data-student="${esc(s.id)}" aria-label="Student drawing"></canvas><p>${esc(d.work.reasoning||'No written thinking yet.')}</p><small>${d.mastery?'Mastery: '+d.mastery.percent+'%':'Mastery not completed'} · ${d.race?d.race.points+' sprint points':'Sprint not started'}</small></button>`}).join('')}</div>`}
function reportHTML(){let lesson=dashboard.lesson;return `<div class="report-header"><div class="eyebrow">END-OF-CLASS LEARNING RECORD</div><h2>Probability of simple events</h2>${ar('تقرير درس احتمال الأحداث البسيطة')}<p>Prepared by Walaa Falah · Professor Dr. Jehan Yousif · Grade 9 girls · Micro-teaching task</p><p>${new Date().toLocaleString('en-GB',{timeZone:'Asia/Dubai'})} · UAE time · Class ${esc(state.code)}</p></div>${statsHTML()}${labMonitor()}${missionControl()}${diagnosticHTML()}<div class="card"><h3>Student progress & involvement</h3><p style="font-size:11px;color:var(--muted);margin:8px 0 15px">Exploration records visits, not proof of understanding. Game accuracy and first video responses provide assessment evidence. Best completed mastery attempt is shown.</p>${dashboard.students.length?studentTable(true):'<p style="margin-top:15px">No students have joined yet.</p>'}</div><div class="card" style="margin-top:20px"><h3>Materials & teaching methods used</h3><div class="material-list"><div><span>▤</span><section><b>Bilingual slide lesson · English / العربية</b><p>Introduction, learning objective, review card, dirham quick check, competition, mastery practice, exit poll, learning report.</p></section></div><div><span>▷</span><section><b>${lesson.videoId?'YouTube video · '+esc(lesson.videoId):'Video not assigned'}</b><p>${lesson.videoId?'https://www.youtube.com/watch?v='+esc(lesson.videoId):'Add an unlisted video from Video & questions.'} · ${lesson.checkpoints.length} timed MCQs</p>${lesson.checkpoints.map(c=>`<p>${formatTime(c.at)} · ${esc(c.en)} ${esc(c.ar)}</p>`).join('')}</section></div><div><span>◈</span><section><b>Visual manipulatives & games</b><p>Stylized UAE dirham faces; fair six-sided dice; equal-sector spinners. ${state.bankSize} bank questions; sprint: 10 × 40 seconds; mastery: 12 × 40 seconds, goal ≥80% (10/12). Legacy dice lab is optional and not tracked.</p></section></div><div><span>◎</span><section><b>Teaching approaches</b><p>Guided inquiry, predict–observe–explain, think–pair–share, movable manipulatives, formative MCQs, timed retrieval practice, individual feedback, exit reflection.</p></section></div></div></div><div class="card" style="margin-top:20px"><h3>Teacher reflection · تأمل المعلمة</h3><p style="margin-top:12px;white-space:pre-wrap">${esc(dashboard.reflection||'Not recorded yet. Complete after teaching; no outcomes have been assumed.')}</p></div><div class="card" style="margin-top:20px"><h3>Individual work & teacher feedback</h3>${dashboard.students.map(s=>{let d=studentStats(s);return `<div class="review-item"><strong>${esc(s.name)}</strong>${labEvidence(s.id)}<p>Thinking: ${esc(d.work.reasoning||'Not submitted')}</p>${evidenceHTML(s.id)}${sampleCards(s.id)}<p>Teacher feedback: ${esc(d.work.feedback||'None yet')}</p><canvas width="700" height="250" class="report-drawing" data-drawing-student="${esc(s.id)}" style="width:60%;display:${d.work.strokes&&JSON.parse(d.work.strokes).length?'block':'none'}"></canvas><p>Exit reflection: ${s.poll===null?'Not submitted':esc(POLLS[s.poll][0])}</p><p>Mastery attempts: ${dashboard.attempts.filter(a=>a.student===s.id&&a.mode==='mastery').length} · ${d.work.strokes&&JSON.parse(d.work.strokes).length?'Drawing included in individual work view.':'No drawing submitted.'}</p></div>`}).join('')}</div>`}
function renderVideoEditor(){let l=state.lesson;$('#teacherPanel').innerHTML=`<div class="grid2"><div class="card"><div class="eyebrow">BUILD A MOMENT OF WONDER</div><h3 style="margin:12px 0">One video. Many thinking moments.</h3><p class="subtle" style="font-size:12px">Add your unlisted YouTube link, then place questions at exact times. Playback pauses until a student answers. The first answer is recorded.</p><form id="videoForm"><label class="field" style="margin-top:22px">YouTube link · رابط الفيديو<input id="videoURL" type="url" placeholder="https://www.youtube.com/watch?v=…" value="${l.videoId?'https://www.youtube.com/watch?v='+esc(l.videoId):''}"></label><div class="lesson-note" style="margin-top:15px">Allow embedding in YouTube Studio. Unlisted videos work; private videos do not. Saving changes resets existing checkpoint responses. Students already on the video slide should reload.</div><div class="grid2" style="margin-top:15px"><label class="field">Source start (seconds)<input id="videoStart" type="number" min="0" value="${l.start||0}"></label><label class="field">Source end (seconds)<input id="videoEnd" type="number" min="1" value="${l.end||7200}"></label></div><div id="checkpointEditors">${l.checkpoints.map((c,i)=>checkpointEditor(c,i)).join('')}</div><button type="button" class="btn secondary small" data-action="add-checkpoint" style="margin-top:18px">+ Add a timed MCQ</button><div class="error" id="videoFormError" style="margin-top:15px" role="alert"></div><button class="btn" type="submit" style="margin-top:20px">Save lesson video & questions →</button></form></div><aside class="stack"><div class="card"><h3 style="font-size:16px">Your teaching flow</h3><div class="rule-list"><div><b>01</b><span><strong>Before watching</strong><br>Ask: where do we see chance in everyday life?</span></div><div><b>02</b><span><strong>During the video</strong><br>Use a short MCQ after an example. Write both English and Arabic in the question and each option.</span></div><div><b>03</b><span><strong>After watching</strong><br>Invite partners to explain their reasoning. Look at individual responses in the live dashboard.</span></div></div></div><div class="lesson-note">Suggested checkpoint: “A fair coin has how many possible outcomes?”<br>“كم عدد النواتج الممكنة لعملة عادلة؟”<br><br>Options: 1 / ١ · 2 / ٢ · 3 / ٣ · 4 / ٤</div></aside></div>`;$('#videoForm').onsubmit=saveVideo}
function checkpointEditor(c={},i=0){return `<div class="checkpoint-editor"><div class="row spread"><strong style="font-size:12px">Thinking stop ${i+1}</strong><button class="btn ghost small" type="button" data-action="remove-checkpoint">Remove ✕</button></div><div class="grid2"><label class="field">Time after trim (seconds) · بعد القص<input type="number" name="at" min="0" max="7200" value="${c.at??30}" required></label><label class="field">Correct option<select name="correct">${['A','B','C','D'].map((x,j)=>`<option value="${j}" ${c.correct===j?'selected':''}>${x}</option>`).join('')}</select></label></div><label class="field">Question · English<input name="en" required maxlength="500" value="${esc(c.en||'')}" placeholder="What is the probability of heads?"></label><label class="field">السؤال بالعربية<input name="ar" dir="rtl" maxlength="500" value="${esc(c.ar||'')}" placeholder="ما احتمال ظهور وجه الدلة؟"></label><label class="field">Worked explanation · شرح خطوات الحل<textarea name="explanation" maxlength="2000" required>${esc(c.explanation||'')}</textarea></label><div class="grid2">${[0,1,2,3].map(j=>`<label class="field">Option ${'ABCD'[j]} · English / العربية<input name="option${j}" maxlength="180" value="${esc(c.options?.[j]||'')}"></label>`).join('')}</div></div>`}
async function saveVideo(e){e.preventDefault();const btn=$('button[type=submit]',e.target);btn.disabled=true;try{let url=$('#videoURL').value.trim(),id='';if(url){let u=new URL(url);if(!['youtube.com','www.youtube.com','m.youtube.com','youtu.be','www.youtube-nocookie.com'].includes(u.hostname))throw new Error('Use a YouTube video link.');id=u.hostname==='youtu.be'?u.pathname.slice(1).split('/')[0]:(u.searchParams.get('v')||u.pathname.split('/').at(-1));if(!/^[\w-]{11}$/.test(id))throw new Error('The video link does not contain a valid video ID.')}const checkpoints=$$('.checkpoint-editor').map(el=>({at:+$('[name=at]',el).value,en:$('[name=en]',el).value,ar:$('[name=ar]',el).value,correct:+$('[name=correct]',el).value,explanation:$('[name=explanation]',el).value,options:[0,1,2,3].map(i=>$(`[name=option${i}]`,el).value).filter(x=>x.trim())}));await api('lesson',{videoId:id,checkpoints,start:+$('#videoStart').value,end:+$('#videoEnd').value});state=await api('state');toast('Video lesson saved. Students can reload to see the updates.');renderVideoEditor()}catch(e){$('#videoFormError').textContent=e.message;btn.disabled=false}}
let previewSlide=0;
function renderPreview(){let c=[cover,()=>`<div class="card"><h2>Watch & wonder</h2><p style="margin-top:20px">${state.lesson.videoId?'Assigned video: '+esc(state.lesson.videoId):'Add your unlisted YouTube video in Video & questions.'}</p><p>${state.lesson.checkpoints.length} timed thinking stops.</p>${state.lesson.checkpoints.map(c=>`<div class="review-item">${formatTime(c.at)} · ${esc(c.en)}${ar(c.ar)}</div>`).join('')}</div>`,reviewSlide,()=>`<div class="card"><h2>The dirham challenge</h2><div class="manipulatives">${coin()}${coin('tails')}</div><p>What is P(heads)? 1 favorable outcome / 2 equally likely outcomes = 1/2.</p>${ar('ما احتمال ظهور وجه الدلة؟ ١/٢')}</div>`,()=>gameIntro('race'),()=>gameIntro('mastery'),()=>`<div class="card"><h2>Exit reflection</h2><div class="poll-options">${POLLS.map(p=>`<div class="poll-option"><strong>${p[2]} ${p[0]}</strong>${ar(p[1])}</div>`).join('')}</div></div>`,()=>`<div class="card"><h2>My learning story</h2><p style="margin-top:20px">Students see their own progress, best completed mastery attempt, and exit reflection. They can print their learning report.</p></div>`];$('#teacherPanel').innerHTML=`<div class="row spread" style="margin-bottom:20px;flex-wrap:wrap"><span class="pill gold">Teacher preview · ${previewSlide+1} / 8</span><div class="row"><button class="btn secondary small" data-action="preview-prev" ${previewSlide===0?'disabled':''}>← Back</button><button class="btn secondary small" data-action="preview-next" ${previewSlide===7?'disabled':''}>Next →</button><button class="btn small" data-action="present-slide">Present this slide</button></div></div><div class="slide">${c[previewSlide]()}</div><div class="lesson-note" style="margin:20px 0">Use “Present this slide” to switch the class to teacher-led mode. Students follow your selected slide. Switch back to student-paced whenever you’re ready.</div>`;enableDrag()}
async function setPace(mode,target=state.control?.slide||0){try{await api('control',{mode,slide:target});state.control={mode,slide:target};toast(mode==='student'?'Students can explore at their own pace.':'Students will follow slide '+(target+1)+'.');await refreshDashboard()}catch(e){toast(e.message)}}
async function studentDetail(id){selectedStudent=id;const s=dashboard.students.find(s=>s.id===id);if(!s)return;let d=studentStats(s);$('#modal').hidden=false;$('#modal').innerHTML=`<section class="modal-card student-detail" role="dialog" aria-modal="true" aria-labelledby="studentTitle"><div class="row spread"><span class="pill ${d.work.help?'coral':'green'}">${d.work.help?'✋ Help requested':'Student work'}</span><button class="icon-btn" data-action="close-modal" aria-label="Close student view">✕</button></div><h2 id="studentTitle">${esc(s.name)}</h2>${progressBubbles(s)}<div id="studentLiveWork"></div><div id="slideSamples"></div><label class="field" style="margin-top:20px">Private feedback · ملاحظات خاصة<textarea id="studentFeedback" maxlength="2000" placeholder="Acknowledge a good idea, then suggest a next step…">${esc(d.work.feedback||'')}</textarea></label><button class="btn" style="margin-top:15px" data-action="send-feedback" data-id="${esc(id)}">Send feedback & acknowledge hand →</button><details style="margin-top:20px"><summary>Assessment evidence · أدلة التعلم</summary><div id="studentEvidence"></div></details></section>`;refreshStudentView();$('#studentFeedback').focus()}
function refreshStudentView(){if(!selectedStudent||!$('#studentLiveWork'))return;let s=dashboard.students.find(s=>s.id===selectedStudent);if(!s)return;let d=studentStats(s);$('#studentLiveWork').innerHTML=`<p class="subtle" style="font-size:11px">Slide ${s.slide+1} · ${esc(steps[s.slide][0])} · ${Date.now()/1000-s.seen<35?'Live now':'Away'}${d.work.help?' · ✋ Help requested':''}</p><div class="student-thinking"><canvas id="studentCanvas" width="700" height="300" aria-label="Student drawing"></canvas><p>${esc(d.work.reasoning||'No written reasoning yet.')}</p></div>`;paintStrokes($('#studentCanvas'),JSON.parse(d.work.strokes||'[]'));if($('#slideSamples')){$('#slideSamples').innerHTML=sampleCards(s.id);$$('#slideSamples canvas').forEach(c=>paintStrokes(c,JSON.parse(dashboard.samples.find(w=>w.student===s.id&&w.slide===+c.dataset.page)?.strokes||'[]')))}$('#studentEvidence').innerHTML=`${labEvidence(s.id)}<p style="font-size:11px;margin:12px 0">Dirham check: ${s.coin===null?'Not answered':s.coin?'Correct':'Needs review'}</p>${state.lesson.checkpoints.map(c=>`<div class="review-item"><b>Video · ${esc(c.en)}</b><p>${d.video[c.id]?(d.video[c.id].correct?'✓ Correct':'✕ Incorrect')+' · '+esc(c.options[d.video[c.id].choice]):'Not answered'}</p></div>`).join('')}${dashboard.attempts.filter(a=>a.student===s.id).map(a=>`<div class="review-item"><b>${a.mode==='race'?'Sprint':'Mastery'} · ${a.correct}/${a.total} correct · ${a.points} pts · ${a.finished?'Complete':'In progress'}</b>${(a.responses||a.review||[]).length?`<details><summary>See submitted responses</summary>${(a.responses||a.review||[]).map((q,i)=>`<p style="font-size:11px;padding:8px 0">${q.correct?'✓':'✕'} ${i+1}. ${esc(q.en)}<br>Your answer: ${q.choice===null?'Timed out':esc(q.choices[q.choice])} · Correct: ${esc(q.choices[q.correctAnswer])}</p>`).join('')}</details>`:''}</div>`).join('')}`}
/* Shared thinking space: text and a normalized vector drawing. */
let workOpen=false, strokes=[], drawing=false, drawCanvas=null, workSaveTimer=null;
function thinkingWidget(){return `<button class="thinking-toggle" data-action="thinking">✎ <span>My thinking space</span><span id="feedbackBadge">${state.work?.feedback?'●':''}</span></button><div class="thinking-panel" id="thinkingPanel" ${workOpen?'':'hidden'}><div class="row spread"><div><h3 style="font-size:15px">Make your thinking visible.</h3>${ar('أظهري طريقة تفكيرك','small')}</div><button class="icon-btn" data-action="thinking" aria-label="Close thinking space">✕</button></div><div class="teacher-feedback" id="teacherFeedback">${state.work?.feedback?'<b>Ms. Walaa’s feedback</b><p>'+esc(state.work.feedback)+'</p>':'Your teacher can see this space and send you feedback.'}</div><div class="lesson-note">Draw it: sketch all six die faces, circle the even outcomes, and explain why P(even) = 3/6. / ارسمي أوجه النرد الستة، وحددي الزوجية، وفسري ٣/٦.</div><label class="field">Explain your idea · اشرحي فكرتك<textarea id="reasoning" maxlength="3000" placeholder="How did you count the possible outcomes?">${esc(state.work?.reasoning||'')}</textarea></label><canvas id="thinkingCanvas" width="700" height="280" aria-label="Draw your sample space" tabindex="0"></canvas><div class="row spread"><button class="btn secondary small" data-action="undo-draw">↶ Undo</button><button class="btn secondary small" data-action="clear-draw">Clear drawing</button><button class="btn small" data-action="save-work">Save work</button></div><div class="row spread" style="margin-top:14px"><button class="btn ${state.work?.help?'coral':'secondary'} small" data-action="raise-hand">${state.work?.help?'✋ Hand raised · Cancel':'✋ I need help'}</button><small id="workStatus">Your teacher sees saved work live.</small></div></div>`}
function addThinkingSpace(){if(state.role!=='student')return;$$('.thinking-toggle,.thinking-panel').forEach(el=>el.remove());app.insertAdjacentHTML('beforeend',thinkingWidget());$('.topbar-actions')?.prepend($('.thinking-toggle'));strokes=JSON.parse(state.work?.strokes||'[]');initCanvas();$('#reasoning').addEventListener('input',()=>{clearTimeout(workSaveTimer);workSaveTimer=setTimeout(saveWork,900)})}
function paintStrokes(canvas,lines){if(!canvas)return;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);ctx.strokeStyle='#175e53';ctx.lineWidth=3;ctx.lineCap='round';ctx.lineJoin='round';for(const line of lines){if(!line.length)continue;ctx.beginPath();line.forEach(([x,y],i)=>i?ctx.lineTo(x*canvas.width,y*canvas.height):ctx.moveTo(x*canvas.width,y*canvas.height));ctx.stroke()}}
function initCanvas(){drawCanvas=$('#thinkingCanvas');if(!drawCanvas)return;paintStrokes(drawCanvas,strokes);drawCanvas.onpointerdown=e=>{if(strokes.length>=150){toast('Drawing is full. Undo or clear a stroke to continue.');return}drawing=true;drawCanvas.setPointerCapture(e.pointerId);strokes.push([]);addPoint(e)};drawCanvas.onpointermove=e=>{if(drawing)addPoint(e)};drawCanvas.onpointerup=()=>{drawing=false;saveWork()};drawCanvas.onpointercancel=()=>{drawing=false;saveWork()}}
function addPoint(e){let r=drawCanvas.getBoundingClientRect(),line=strokes.at(-1);if(line.length<400)line.push([Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))]);paintStrokes(drawCanvas,strokes)}
async function saveWork(){if(!$('#reasoning'))return;clearTimeout(workSaveTimer);const reasoning=$('#reasoning').value;if(!reasoning.trim()&&!strokes.length&&!(state.samples||[]).some(w=>w.slide===slide))return;const copy=JSON.parse(JSON.stringify(strokes));$('#workStatus').textContent='Saving…';try{await api('work',{reasoning,strokes:copy,slide});state.work={...state.work,reasoning,strokes:JSON.stringify(copy)};state.samples=state.samples||[];const at=state.samples.findIndex(w=>w.slide===slide);const sample={slide,reasoning,strokes:JSON.stringify(copy)};if(at<0)state.samples.push(sample);else state.samples[at]=sample;$('#workStatus').textContent='Saved ✓ · Teacher can see it'}catch(e){$('#workStatus').textContent='Not saved · retry';toast(e.message)}}
async function pollClassroom(){if(!state||state.role!=='student')return;try{let d=await api('classroom');let prior=state.work?.feedback;state.control=d.control;state.work={...state.work,feedback:d.work.feedback,help:d.work.help};if($('#teacherFeedback'))$('#teacherFeedback').innerHTML=d.work.feedback?'<b>Ms. Walaa’s feedback</b><p>'+esc(d.work.feedback)+'</p>':'Your teacher can see this space and send feedback.';if(d.work.feedback&&d.work.feedback!==prior){toast('New feedback from Ms. Walaa · ملاحظات جديدة');$('#feedbackBadge').textContent='●'}if(d.control.mode==='teacher'&&slide!==d.control.slide){await navigate(d.control.slide,true);toast('Your teacher moved the class to slide '+(slide+1));}$('.breadcrumb').innerHTML=`${d.control.mode==='teacher'?'Teacher-led · مع المعلمة':'Student-paced · حسب سرعتك'} <span>/ &nbsp; Simple probability</span>`;linked=true;syncStatus();updateAchievementRibbon();if(slide===4)refreshLeaderboard()}catch{linked=false;syncStatus()}}
function enableDrag(){$$('[data-drag]').forEach(el=>{let originX=0,originY=0,startX=0,startY=0,base=el.style.transform;el.onpointerdown=e=>{if(e.button!==0)return;el.setPointerCapture(e.pointerId);startX=e.clientX-originX;startY=e.clientY-originY;el.style.zIndex='8';el.dataset.moving='1'};el.onpointermove=e=>{if(!el.dataset.moving)return;originX=Math.max(-100,Math.min(100,e.clientX-startX));originY=Math.max(-80,Math.min(80,e.clientY-startY));el.style.transform=`translate(${originX}px,${originY}px) ${base}`};el.onpointerup=el.onpointercancel=()=>delete el.dataset.moving;el.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();originX=Math.max(-100,Math.min(100,originX+(e.key==='ArrowLeft'?-10:e.key==='ArrowRight'?10:0)));originY=Math.max(-80,Math.min(80,originY+(e.key==='ArrowUp'?-10:e.key==='ArrowDown'?10:0)));el.style.transform=`translate(${originX}px,${originY}px) ${base}`}})}
/* Print artifacts use dedicated pages; no dashboards or controls leak onto slides. */
function printPage(title,content,i){return `<section class="print-page"><div class="eyebrow">CHANCE STUDIO · GRADE 9 · ${esc(title)}</div>${content}<div class="print-footer">Probability of simple events · Walaa Falah · Dr. Jehan Yousif · Page ${i}</div></section>`}
function simpleQuestion(q,i){return `<div class="print-question"><p><b>${i+1}. ${esc(q.en)}</b></p>${ar(q.ar)}${q.detail&&typeof q.detail==='object'?`<p>Equal sectors: ${q.detail.segments} · Coral sectors: ${q.detail.red}</p>`:''}<div class="choices-print">${q.choices.map((c,j)=>`<span>${'ABCD'[j]}. ${esc(c)}</span>`).join('')}</div></div>`}
async function printLesson(){let bank=[];if(state.role==='teacher'){try{bank=(await api('materials')).bank}catch(e){toast(e.message);return}}let pages=[printPage('Introduction',cover(),1),printPage('Video & reflection',`<h2>Watch & wonder · شاهدي وفكري</h2><p>${state.lesson.videoId?'Video: https://www.youtube.com/watch?v='+esc(state.lesson.videoId):'Your teacher will add the lesson video.'}</p>${state.lesson.checkpoints.map((c,i)=>`<div class="print-question"><p><b>${formatTime(c.at)} · ${esc(c.en)}</b></p>${ar(c.ar)}<div class="choices-print">${c.options.map((o,j)=>`<span>${'ABCD'[j]}. ${esc(o)}</span>`).join('')}</div></div>`).join('')}<h3 style="margin-top:30px">What did you notice? · ماذا لاحظتِ؟</h3><p style="margin-top:20px">___________________________________________________________________________________</p>`,2),printPage('Revision card',printRevisionCard(),3),printPage('Dirham challenge',`<h2>One dirham. Two possibilities.</h2>${ar('درهم واحد، نتيجتان محتملتان')}<div class="manipulatives">${coin('heads')}${coin('tails')}</div><p>The dallah face is “heads.” The value face is “tails.” Both are equally likely.</p>${ar('وجه الدلة هو الوجه المطلوب ووجه الرقم هو الوجه الآخر، ولهما الاحتمال نفسه.')}<h3 style="margin-top:25px">What is P(heads) on one flip?</h3><p>□ 1/4 &nbsp;&nbsp;&nbsp; □ 1/2 &nbsp;&nbsp;&nbsp; □ 1 &nbsp;&nbsp;&nbsp; □ 0</p><p style="margin-top:30px">Explain your reasoning: _________________________________________________________________</p>`,4)];pages.push(...Object.values(EXAMPLES).map((q,i)=>printPage('Worked example · '+q.name,`<h2>${q.event}</h2>${ar(q.eventAr)}<p>1. Sample space: ${esc(q.items.join(', '))} — ${q.d} equally likely outcomes.</p><p>2. Favorable outcomes: ${esc(q.wanted.map(i=>q.items[i]).join(', '))} — ${q.n} favorable outcomes.</p><p>3. P(event) = favorable outcomes / all equally likely outcomes.</p><div class="math">\\(P(E)=${q.math}\\)</div><p>4. ${q.why}</p>${ar(q.whyAr)}<p>5. Explain why the numerator counts outcomes, not their values. / فسري لماذا نعد النواتج ولا نجمع قيمها.</p>`,5+i)));if(bank.length){let race=[...bank.filter(q=>q.kind==='coin').slice(0,2),...bank.filter(q=>q.kind==='dice').slice(0,3),...bank.filter(q=>q.kind==='spinner').slice(0,5)],mastery=[...bank.filter(q=>q.kind==='coin').slice(2,4),...bank.filter(q=>q.kind==='dice').slice(3,7),...bank.filter(q=>q.kind==='spinner').slice(5,11)];for(const [label,questions] of [['Sprint · 10 questions',race],['Mastery · 12 questions',mastery]])for(let start=0;start<questions.length;start+=4)pages.push(printPage(label,`<h2>${label}</h2><p>Name: ______________________ &nbsp; Class: __________ &nbsp; 40 seconds per question · ٤٠ ثانية لكل سؤال</p>${questions.slice(start,start+4).map((q,i)=>simpleQuestion(q,start+i)).join('')}`,pages.length+1));pages.push(printPage('Teacher answer key',`<h2>Teacher answer key · مفتاح الإجابة</h2><p>Printed worksheets use fixed sample sets. Online games use randomized selections.</p><div class="grid2"><div><h3>Sprint</h3>${race.map((q,i)=>`<p>${i+1}. ${'ABCD'[q.correct]} · ${q.choices[q.correct]}</p>`).join('')}</div><div><h3>Mastery · ≥10 / 12</h3>${mastery.map((q,i)=>`<p>${i+1}. ${'ABCD'[q.correct]} · ${q.choices[q.correct]}</p>`).join('')}</div></div>`,pages.length+1))}else pages.push(printPage('Games',`<h2>Practice for mastery</h2><div class="grid2"><div class="card"><h3>Probability sprint</h3><p>10 questions · 40 seconds each<br>Correct answer: 100 points + up to 100 speed points.</p></div><div class="card"><h3>Mastery quest</h3><p>12 questions · 40 seconds each<br>Goal: 10/12 correct (83.3%) to reach at least 80%.</p></div></div><p style="margin-top:30px">Play the games in the connected classroom. The teacher can print the full practice worksheets.</p>`,5));pages.push(printPage('Exit reflection',`<h2>How does probability feel now?</h2>${ar('ما مدى فهمك للاحتمالات الآن؟')}<div class="poll-options">${POLLS.map(p=>`<div class="poll-option">□ ${p[0]} ${ar(p[1])}</div>`).join('')}</div><h3>One thing I learned · شيء تعلمته</h3><p style="margin-top:25px">____________________________________________________________________________</p><h3 style="margin-top:30px">A question I still have · سؤال ما زال لدي</h3><p style="margin-top:25px">____________________________________________________________________________</p>`,pages.length+1));doPrint(pages.join(''))}
function doPrint(html){$('#printRoot').innerHTML=html;$$('#printRoot canvas[data-sample-student]').forEach(c=>{const w=dashboard?.samples?.find(w=>w.student===c.dataset.sampleStudent&&w.slide===+c.dataset.page);paintStrokes(c,JSON.parse(w?.strokes||'[]'))});Promise.resolve(window.MathJax?.startup?.promise).then(()=>window.MathJax?.typesetPromise?.([$('#printRoot')])).catch(()=>{}).finally(()=>setTimeout(()=>window.print(),150))}
function printProgress(){const r=bestAttempt('race'),m=bestAttempt('mastery');doPrint(`<section class="print-report"><div class="eyebrow">PERSONAL LEARNING RECORD</div><h1 style="margin:20px 0">${esc(state.student.name)}</h1><p>Probability of simple events · Grade 9 · Walaa Falah</p><p>${new Date().toLocaleDateString('en-GB',{timeZone:'Asia/Dubai'})}</p>${storySlide()}<div class="card"><h3>My thinking & teacher feedback</h3><p>${esc(state.work?.reasoning||'No written work submitted.')}</p><canvas id="printDrawing" width="700" height="280" style="width:70%"></canvas><p><b>Teacher feedback:</b> ${esc(state.work?.feedback||'None yet.')}</p></div>${[r,m].filter(Boolean).map(a=>`<div class="card"><h3>${a.mode==='race'?'Sprint':'Best mastery'} · ${a.percent}%</h3>${a.review.map((q,i)=>`<div class="print-question">${q.correct?'✓':'✕'} ${i+1}. ${esc(q.en)} ${ar(q.ar)}<p>Your answer: ${q.choice===null?'Timed out':esc(q.choices[q.choice])} · Correct: ${esc(q.choices[q.correctAnswer])}</p></div>`).join('')}</div>`).join('')}</section>`);paintStrokes($('#printDrawing'),JSON.parse(state.work?.strokes||'[]'))}
async function printReport(){await refreshDashboard();doPrint(`<section class="print-report">${reportHTML()}<div class="print-footer">This record reflects submissions received at print time. Unfinished attempts and unsubmitted work are shown separately.</div></section>`);$$('#printRoot canvas[data-drawing-student]').forEach(c=>{let w=dashboard.work.find(w=>w.student===c.dataset.drawingStudent);paintStrokes(c,JSON.parse(w?.strokes||'[]'))})}
function exportCSV(){const header=['Student','Slides visited','Current slide','Video answered','Video correct','Dirham correct','Sprint points','Sprint accuracy (complete)','Mastery best accuracy','Mastery attempts','Exit reflection','Reasoning','Teacher feedback'];let rows=dashboard.students.map(s=>{let d=studentStats(s);return [s.name,d.visited.length,s.slide+1,Object.keys(d.video).length,Object.values(d.video).filter(v=>v.correct).length,s.coin===null?'Not answered':s.coin?'Yes':'No',d.race?.points??'',d.race?.finished?d.race.percent:'Incomplete',d.mastery?.percent??'Not completed',dashboard.attempts.filter(a=>a.student===s.id&&a.mode==='mastery').length,s.poll===null?'Not submitted':POLLS[s.poll][0],d.work.reasoning||'',d.work.feedback||'']});let csv='\uFEFF'+[header,...rows].map(row=>row.map(v=>'"'+String(v).replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));let a=document.createElement('a');a.href=url;a.download='probability-class-report.csv';a.click();URL.revokeObjectURL(url)}
/* Event delegation keeps slide controls accessible after live renders. */
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;try{switch(action){case 'login-role':loginRole=b.dataset.role;login();break;case 'logout':if(state?.role==='student')await saveWork();await api('logout',{});clearIntervals();state=null;login();break;case 'menu':$('.sidebar').classList.toggle('open');break;case 'navigate':if(state.role==='teacher'){toast('This is a preview. Students play from their own accounts.');break}await navigate(+b.dataset.slide);$('.sidebar').classList.remove('open');break;case 'prev':await navigate(slide-1);break;case 'next':await navigate(slide+1);break;case 'print-lesson':await printLesson();break;case 'print-progress':printProgress();break;case 'print-plan':await printPlan();break;case 'save-reflection':await saveReflection();break;case 'print-report':await printReport();break;case 'export-csv':exportCSV();break;case 'coin-answer':{const r=await api('coin',{choice:+b.dataset.choice});state.student.coin=Number(r.correct);$('#coinFeedback').innerHTML=`<div class="feedback ${r.correct?'':'wrong'}">${r.correct?'✓ Exactly!':'Let’s count together.'} P(heads) = 1 favorable outcome ÷ 2 equally likely outcomes = <b>1/2</b>.${ar('احتمال وجه الدلة = ناتج مرغوب واحد ÷ نتيجتين متساويتي الاحتمال = ١/٢.','small')}<ol dir="rtl"><li>نكتب فضاء العينة: {وجه الدلة، وجه الرقم}، وعدده ٢.</li><li>الحدث المطلوب هو وجه الدلة فقط؛ عدد النواتج المرغوبة ١.</li><li>نقسم ١ على ٢، ولا نستعمل ١/٤ لأن التجربة قلب واحد وليست قلبين.</li><li>الاحتمال ليس ١ لأن النتيجة غير مؤكدة، وليس ٠ لأنها ممكنة.</li></ol><span class="math">\\(P(H)=\\frac{1}{2}=0.5\\)</span></div>`;$$('[data-action="coin-answer"]').forEach(x=>{x.classList.remove('correct','wrong');if(+x.dataset.choice===1)x.classList.add('correct');else if(x===b)x.classList.add('wrong')});break}case 'flip':{flipCount++;$$('.coin-stage .coin-obj').forEach(el=>{el.classList.remove('coin-flip');void el.offsetWidth;el.classList.add('coin-flip')});let heads=Math.random()<.5;$('#flipResult').textContent=(heads?'Heads · وجه الدلة':'Tails · وجه الرقم')+' — P(heads) stays 1/2 on the next fair flip. / الاحتمال لا يتغير.';break}case 'spin':{spin+=720+Math.random()*360;$$('.spinner-arrow').forEach(el=>el.style.transform=`rotate(${spin}deg)`);if($('#exploreResult'))$('#exploreResult').textContent='The spinner has equal sectors. P(coral) = 1/4, whatever the last result. / احتمال المرجاني = ١/٤.';break}case 'roll':{let n=1+Math.floor(Math.random()*6);const old=$('.tool-card .die-obj');if(old){old.outerHTML=die(n,true);enableDrag()}if($('#exploreResult'))$('#exploreResult').textContent=`You rolled ${n}. Each number still has probability 1/6 on the next roll. / لكل عدد احتمال ١/٦.`;break}case 'start-game':if(state.role!=='student'){toast('Sign in as a student in a separate browser to play.');break}b.disabled=true;await startGame(b.dataset.mode);b.disabled=false;break;case 'resume-game':storeAttempt(await api('resume',{attempt:activeGame.id}));renderGame();break;case 'game-answer':await answerGame(+b.dataset.choice);break;case 'retry-game':{const next=await api('state');state.attempts=next.attempts;activeGame=state.attempts.find(a=>a.id===activeGame.id);if(activeGame)activeGame.receivedAt=Date.now();renderGame();break}case 'poll':await api('poll',{choice:+b.dataset.choice});state.student.poll=+b.dataset.choice;$('#slideContent').innerHTML=pollSlide();break;case 'video-answer':await answerCheckpoint(+b.dataset.choice);break;case 'hold-video':clearTimeout(autoResumeTimer);toast('Read at your pace, then press Continue. / اقرئي ثم اضغطي متابعة.');break;case 'video-continue':continueVideo();break;case 'video-help':toast('Check your connection and YouTube embedding permissions. Ask Ms. Walaa if playback is unavailable.');break;case 'teacher-tab':teacherTab=b.dataset.tab;renderTeacher();if(['monitor','report'].includes(teacherTab))await refreshDashboard();break;case 'add-checkpoint':if($$('.checkpoint-editor').length>=15){toast('Use up to 15 thinking stops.');break}$('#checkpointEditors').insertAdjacentHTML('beforeend',checkpointEditor({},$$('.checkpoint-editor').length));break;case 'remove-checkpoint':b.closest('.checkpoint-editor').remove();break;case 'preview-prev':previewSlide=Math.max(0,previewSlide-1);renderPreview();break;case 'preview-next':previewSlide=Math.min(7,previewSlide+1);renderPreview();break;case 'present-slide':await setPace('teacher',previewSlide);toast('Presenting slide '+(previewSlide+1)+' to the class.');break;case 'pace':await setPace(b.dataset.mode);break;case 'view-mode':galleryMode=!galleryMode;renderDashboardPanel();break;case 'student-detail':await studentDetail(b.dataset.id);break;case 'close-modal':selectedStudent=null;$('#modal').hidden=true;break;case 'send-feedback':b.disabled=true;await api('feedback',{student:b.dataset.id,feedback:$('#studentFeedback').value});toast('Feedback sent privately to the student.');b.disabled=false;await refreshDashboard();break;case 'thinking':workOpen=!workOpen;$('#thinkingPanel').hidden=!workOpen;if(workOpen){$('#feedbackBadge').textContent='';$('#reasoning').focus()}break;case 'undo-draw':strokes.pop();paintStrokes(drawCanvas,strokes);await saveWork();break;case 'clear-draw':strokes=[];paintStrokes(drawCanvas,strokes);await saveWork();break;case 'save-work':await saveWork();break;case 'raise-hand':{let help=!state.work?.help;await api('work',{help});state.work={...state.work,help:Number(help)};b.textContent=help?'✋ Hand raised · Cancel':'✋ I need help';b.classList.toggle('coral',help);toast(help?'Ms. Walaa can see your raised hand.':'Hand lowered.');break}}}catch(err){toast(err.message);b.disabled=false}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!activeCheckpoint){$('#modal').hidden=true;selectedStudent=null;if($('.sidebar'))$('.sidebar').classList.remove('open');if($('#thinkingPanel')){$('#thinkingPanel').hidden=true;workOpen=false}}if(e.key==='Tab'&&!$('#modal').hidden){const els=$$('button:not(:disabled),input,textarea,select,[tabindex="0"]',$('#modal'));const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
(async()=>{try{await api('health');await loadState()}catch(e){login();if(!e.message.includes('Please sign in'))$('#loginError').textContent=e.message}})();
let planHTML='';
function inlineMD(s){return esc(s).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>')}
function markdownPlan(md){const lines=md.split('\n');let out='',table=false,list=false;const close=()=>{if(table){out+='</tbody></table></div>';table=false}if(list){out+='</ul>';list=false}};for(let line of lines){if(line.startsWith('|')){if(/^\|[\s:|-]+\|$/.test(line))continue;const cells=line.split('|').slice(1,-1).map(x=>x.trim());if(!table){if(list){out+='</ul>';list=false}out+='<div class="table-wrap"><table><thead><tr>'+cells.map(x=>'<th>'+inlineMD(x)+'</th>').join('')+'</tr></thead><tbody>';table=true}else out+='<tr>'+cells.map(x=>'<td>'+inlineMD(x)+'</td>').join('')+'</tr>';continue}if(table){out+='</tbody></table></div>';table=false}if(/^#{1,3} /.test(line)){close();let n=line.match(/^#+/)[0].length;out+=`<h${n}>${inlineMD(line.replace(/^#+ /,''))}</h${n}>`}else if(/^[-\d]+[.)]? /.test(line)){if(!list){out+='<ul>';list=true}out+='<li>'+inlineMD(line.replace(/^[-\d]+[.)]? /,''))+'</li>'}else{if(list){out+='</ul>';list=false}if(line.trim())out+='<p>'+inlineMD(line)+'</p>'}}close();return out}
async function getPlan(){if(!planHTML){const r=await fetch('lesson-plan.md');if(!r.ok)throw new Error('Could not load the lesson plan.');planHTML=markdownPlan(await r.text())}return planHTML}
async function renderPlan(){const panel=$('#teacherPanel');panel.innerHTML='<div class="loading">Loading lesson plan…</div>';try{const html=await getPlan();if(teacherTab!=='plan')return;panel.innerHTML=`<div class="row spread" style="margin-bottom:20px;flex-wrap:wrap"><span class="pill green">ASSURE · 12 rubric criteria · خطة متكاملة</span><div class="row"><a class="btn secondary small" href="lesson-plan.md" download>Download plan ↓</a><button class="btn small" data-action="print-plan">Print lesson plan ▤</button></div></div><div class="lesson-note" style="margin-bottom:20px">20-minute micro-teaching presentation + independent mastery extension. Aligned to the provided assignment rubric; implementation evidence is collected during class.${ar('عرض مصغّر مدته ٢٠ دقيقة، ثم نشاط إتقان مستقل. الخطة مرتبطة بمعايير الملف المرفق.','small')}</div><article class="card lesson-plan" lang="ar" dir="rtl">${html}</article><section class="card" style="margin:20px 0"><h3>Teacher reflection · تأمل المعلمة بعد التنفيذ</h3><p class="subtle" style="font-size:12px;margin:12px 0">Record what actually happened, participation, timing, misconceptions, and your next teaching step. Saved notes are included in the class report.</p><label class="field"><span class="sr-only">Teacher reflection</span><textarea id="reflectionText" dir="auto" maxlength="6000" style="min-height:150px" placeholder="ما الذي نجح؟ ما الدليل؟ ما الذي سأعدله في الحصة القادمة؟">${esc(dashboard?.reflection||'')}</textarea></label><button class="btn small" style="margin-top:15px" data-action="save-reflection">Save reflection · حفظ التأمل</button></section>`}catch(e){panel.innerHTML=`<div class="error">${esc(e.message)}</div>`}}
async function printPlan(){try{const html=await getPlan();doPrint(`<article class="print-plan lesson-plan" dir="rtl" lang="ar">${html}</article>`)}catch(e){toast(e.message)}}
async function saveReflection(){await api('reflection',{content:$('#reflectionText').value});if(dashboard)dashboard.reflection=$('#reflectionText').value;toast('Reflection saved and included in the class report. / تم حفظ التأمل')}
function workedSolution(q){const answer=q.choices[q.correctAnswer??q.correct];const numbers=q.explanation?.match(/\d+/g)||['1','2'];const [n,d]=numbers;const sample=q.kind==='coin'?'Heads / وجه الدلة، Tails / وجه الرقم':q.kind==='dice'?'1, 2, 3, 4, 5, 6':typeof q.detail==='object'?Array.from({length:q.detail.segments},(_,i)=>i+1).join(', '):q.detail;return `<section class="worked"><h3>How to solve · كيف نحل؟</h3><p>${esc(q.en)}</p>${ar(q.ar)}<ol><li>List all equally likely outcomes. / نكتب جميع النواتج المتساوية الاحتمال.<p>${esc(sample)}</p></li><li>Count the outcomes requested in the question. / نعدّ النواتج التي تحقق الحدث المطلوب: <b>${n}</b>.</li><li>Divide favorable outcomes by all outcomes. / نقسم النواتج المرغوبة على جميع النواتج: <span class="math">\\(P(E)=\\frac{${n}}{${d}}\\)</span></li><li>Choose the equivalent answer: <b>${esc(answer)}</b>. / نختار الكسر المكافئ، ونتحقق أن الاحتمال بين صفر وواحد.</li></ol><p class="lesson-note">${q.kind==='spinner'?'Count sectors, not colors; this rule assumes equal sector sizes. / نعد القطاعات لا عدد الألوان، ويشترط تساوي مساحاتها.':q.kind==='dice'?'For an even number, the favorable outcomes are 2, 4, 6. For one specified face there is just one. / للعدد الزوجي النواتج ٢،٤،٦، أما لوجه محدد فهناك ناتج واحد.':'A previous flip does not change the next fair flip. / نتيجة القلب السابق لا تغير احتمال القلب المستقل التالي.'}</p></section>`}
function evidenceHTML(id){return dashboard.attempts.filter(a=>a.student===id).map(a=>`<details open class="evidence"><summary>${a.mode==='race'?'Sprint · السباق':'Mastery · الإتقان'} — ${a.index}/${a.total} · ${a.finished?'Complete':'In progress'}</summary>${(a.responses||a.review||[]).map((q,i)=>`<div class="print-question"><b>${i+1}. ${esc(q.en)}</b>${ar(q.ar)}<p>${q.choice===null?'Timed out · انتهى الوقت':esc(q.choices[q.choice])} · ${q.correct?'✓':'✕'} · Correct: ${esc(q.choices[q.correctAnswer])} · ${q.seconds}s</p>${!q.correct?workedSolution(q):''}</div>`).join('')}</details>`).join('')}
function diagnosticHTML(){if(!dashboard?.students.length)return '';return `<section class="card diagnostics" style="margin:20px 0"><h3>Learning needs & intervention · مواطن الضعف والتدخل</h3><p class="subtle">Accuracy uses submitted and timed-out answers. Visits indicate participation, not understanding. / الدقة من الإجابات، وزيارة الشرائح ليست دليلاً على الفهم.</p><div class="table-wrap"><table><thead><tr><th>Student</th><th>Coin · العملة</th><th>Dice · النرد</th><th>Spinner · القرص</th><th>Engagement · التفاعل</th><th>Suggested intervention · التدخل</th></tr></thead><tbody>${dashboard.students.map(s=>{const all=dashboard.attempts.filter(a=>a.student===s.id).flatMap(a=>a.responses||a.review||[]);let weaknesses=[];const cells=['coin','dice','spinner'].map(kind=>{let r=all.filter(q=>q.kind===kind),right=r.filter(q=>q.correct).length,pct=r.length?Math.round(right/r.length*100):null;if(r.length>=2&&pct<80)weaknesses.push(kind);return `<td>${pct===null?'Not assessed · لم يقس':`${right}/${r.length} · ${pct}%`}<br><small>${r.filter(q=>q.choice===null).length} timeouts</small></td>`}).join('');const d=studentStats(s);const actions=[...weaknesses.map(k=>({coin:'Model both faces / نمذجة وجهي العملة',dice:'List outcomes 1–6 and circle favorable ones / كتابة النواتج وتحديد المرغوب',spinner:'Label equal sectors and count the target color / ترقيم القطاعات وعد اللون المطلوب'}[k])),...(all.filter(q=>q.choice===null).length?['Check reading/time needs / تحققي من احتياج القراءة والوقت']:[]),...(d.work.help?['Respond to raised hand / استجيبي لطلب المساعدة']:[])];return `<tr><td>${esc(s.name)}</td>${cells}<td>${all.length} answers · ${d.visited.length}/8 slides<br>${d.work.reasoning?'Written reasoning ✓':'No reasoning yet'} · ${Object.keys(d.video).length} video responses</td><td>${actions.join('<br>')||'Gather more evidence or offer an extension. / اجمعي أدلة إضافية أو قدمي إثراء.'}<br><button class="btn small secondary no-print" data-action="student-detail" data-id="${s.id}">Review & intervene</button></td></tr>`}).join('')}</tbody></table></div><p class="subtle">Flags require at least two responses per topic; they suggest a review, not a diagnosis. Repeated attempts are included. / المؤشرات اقتراح للمراجعة وتشمل المحاولات المتكررة.</p></section>`}
let mathPending=false;
function scheduleMath(){if(mathPending)return;mathPending=true;setTimeout(async()=>{try{await window.MathJax?.startup?.promise;const nodes=$$('.math:not([data-typeset])');if(nodes.length&&window.MathJax?.typesetPromise){nodes.forEach(n=>n.dataset.typeset='1');await MathJax.typesetPromise(nodes)}}catch{}finally{mathPending=false}},80)}
new MutationObserver(records=>{if(records.some(r=>[...r.addedNodes].some(n=>n.nodeType===1&&(n.matches?.('.math')||n.querySelector?.('.math')))))scheduleMath()}).observe(document.body,{childList:true,subtree:true});
function continueVideo(){clearTimeout(autoResumeTimer);if(!activeCheckpoint)return;const panel=$('#videoQuestion');if(panel){panel.hidden=true;panel.innerHTML=''}$('.video-screen')?.classList.remove('answering');activeCheckpoint=null;player?.playVideo();}
function progressBubbles(s){const d=studentStats(s);return `<div class="activity-bubbles" aria-label="Activity progress">${steps.map((step,i)=>{let status=d.visited.includes(i)?'visited':'';if(i===4&&d.race?.finished)status=d.race.percent>=80?'achieved':'support';if(i===5&&d.mastery)status=d.mastery.mastered?'achieved':'support';if(i===3&&s.coin!==null)status=s.coin?'achieved':'support';if(i===6&&s.poll!==null)status='achieved';return `<span class="bubble ${status} ${s.slide===i?'current':''}" title="${esc(step[0])}">${i+1}</span>`}).join('')}</div><p class="bubble-legend">Green: achieved · Coral: review · Ring: current slide<br>أخضر: أنجزت · مرجاني: مراجعة · إطار: الشريحة الحالية</p>`}
function slideThumbnail(s){return `<div class="slide-thumbnail"><span class="eyebrow">SLIDE ${s.slide+1} · ${esc(steps[s.slide][1])}</span><h3>${esc(steps[s.slide][0])}</h3><div class="mini-manipulatives">${s.slide===1?'▷':s.slide===3?'◉ ◉':s.slide===4||s.slide===5?'⚀  ◴  ◉':'✎  ◈'}</div><p>${s.slide===4||s.slide===5?'Practice & explain · حل وتفسير':s.slide===1?'Watch · answer · review':'Explore · draw · reflect'}</p></div>`}
function sampleCards(id){return `<div class="sample-grid">${(dashboard.samples||[]).filter(w=>w.student===id).map(w=>`<article class="sample-card"><h4>Slide ${w.slide+1} · ${esc(steps[w.slide][0])}</h4><canvas width="600" height="240" data-page="${w.slide}" data-sample-student="${id}"></canvas><p dir="auto">${esc(w.reasoning||'Drawing response · إجابة بالرسم')}</p></article>`).join('')}</div>`}
